    64	/// Resolve a bare `(name, ns)` from the smallest scope enclosing `(path, byte)`.
    65	fn resolve_bare_at(
    66	    g: &ScopeGraph,
    67	    fs: &BTreeMap<String, ParsedFile>,
    68	    edition: u16,
    69	    path: &str,
    70	    byte: usize,
    71	    name: &str,
    72	    ns: NamespaceId,
    73	) -> Resolution {
    74	    let fid = file_id(fs, path).expect("file id");
    75	    let from = enclosing_scope(g, fid, byte)
    76	        .unwrap_or_else(|| panic!("no enclosing scope at {path}:{byte}"));
    77	    let pol = RustPolicy::new(g, edition);
    78	    let q = ResolveQuery {
    79	        name: name.to_string(),
    80	        ns,
    81	        from,
    82	        at: SourceLoc { file: fid, byte },
    83	        cfg: Default::default(),
    84	        ctx: Default::default(),
    85	    };
    86	    resolve(g, &q, &pol)
    87	}
