    41	/// Return the nearest visible value binding named `name` at `(file, at_byte)`.
    42	pub fn lookup_visible_binding<'a>(
    43	    graph: &'a ScopeGraph,
    44	    file: FileId,
    45	    at_byte: usize,
    46	    name: &str,
    47	) -> Option<&'a Binding> {
    48	    let at = SourceLoc {
    49	        file,
    50	        byte: at_byte,
    51	    };
    52	    let mut cur = enclosing_scope(graph, file, at_byte);
    53	    while let Some(scope_id) = cur {
    54	        let mut matches = graph.bindings.iter().filter(|binding| {
    55	            binding.scope == scope_id
    56	                && binding.name == name
    57	                && binding.ns == NS_VALUE
    58	                && matches!(&binding.target, BindTarget::Resolved(Target::Local(_)))
    59	                && vis_extent_covers(binding, &at)
    60	        });
    61	        let first = matches.next();
    62	        if matches.next().is_some() {
    63	            return None;
    64	        }
    65	        if first.is_some() {
    66	            return first;
    67	        }
    68	        if macro_wildcard_poisons(graph, scope_id, &at) {
    69	            return None;
    70	        }
    71	        let kind = match graph.scope(scope_id) {
    72	            Some(scope) => &scope.kind,
    73	            None => return None,
    74	        };
    75	        if !matches!(
    76	            kind,
    77	            ScopeKind::Block | ScopeKind::Callable | ScopeKind::Type
    78	        ) {
    79	            break;
    80	        }
    81	        cur = graph.parent_of(scope_id);
    82	    }
    83	    None
    84	}
