    86	fn vis_extent_covers(binding: &Binding, at: &SourceLoc) -> bool {
    87	    if binding.vis_extents.is_empty() {
    88	        return true;
    89	    }
    90	    binding
    91	        .vis_extents
    92	        .iter()
    93	        .any(|span| span.lo.file == at.file && at.byte >= span.lo.byte && at.byte < span.hi.byte)
    94	}
    95	
    96	fn macro_wildcard_poisons(
    97	    graph: &ScopeGraph,
    98	    scope: crate::name_resolution::types::ScopeId,
    99	    at: &SourceLoc,
   100	) -> bool {
   101	    graph.macro_wildcards.iter().any(|wildcard| {
   102	        wildcard.scope == scope
   103	            && wildcard.ns == NS_VALUE
   104	            && wildcard.range.lo.file == at.file
   105	            && at.byte >= wildcard.range.lo.byte
   106	            && at.byte < wildcard.range.hi.byte
   107	    }) || graph.edges.iter().any(|edge| {
   108	        edge.from == scope
   109	            && edge.kind == EK_GLOB
   110	            && matches!(&edge.to, BindTarget::Pending(_, _))
   111	            && edge.vis_range.as_ref().is_none_or(|span| {
   112	                span.lo.file == at.file && at.byte >= span.lo.byte && at.byte < span.hi.byte
   113	            })
   114	    })
   115	}
